window.DeskData.define("desk/procedures/catalog.json",{"workflows":[{"id":"board-meeting","title":"Convene a Board meeting","category":"Board governance","summary":"Prepare the notice and agenda, establish quorum and take the minutes through signature.","scope":"Ordinary Board meeting of an Indian company. Check class exemptions, the articles and the applicable SS-1 scope. A one-director OPC has a separate procedure.","related":["act-173","act-174","act-118","act-184","rule-board-3","lodr-29","lodr-30","act-175","act-117","act-179"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Set the meeting date","detail":"Check the previous meeting, the statutory interval, the articles and any class exemption. Reserve a venue or video facility and confirm who is authorised to convene the meeting.","reference":"Section 173 · SS-1, paragraphs 1–2"},{"title":"Send notice and papers","detail":"Give each director written notice, the agenda and supporting papers. Ordinarily allow at least seven days, plus postal service time where applicable. For urgent business at shorter notice, document the reason and follow the independent-director safeguards.","reference":"Section 173(3) · SS-1, paragraph 1.3"},{"title":"Check exchange intimation","detail":"For a listed company, match the agenda to Regulation 29 and schedule any required advance intimation before the meeting. Allocate responsibility for reporting any disclosable decision.","reference":"LODR Regulations 29 and 30"},{"title":"Record attendance and decisions","detail":"Check quorum at the start and for each item. Record attendance mode, declarations of interest, abstentions, decisions, dissent and the person responsible for each action.","reference":"Sections 174 and 184 · SS-1, paragraphs 3–5"},{"title":"Finalise the minutes","detail":"Circulate the draft within 15 days of conclusion. Allow seven days from circulation for directors’ comments. Enter the minutes within 30 days, arrange signature and circulate the signed copy in accordance with SS-1.","reference":"Section 118 · SS-1, paragraphs 7.4–7.6"},{"title":"Close filings and actions","detail":"Check each decision for event disclosure, a registrable resolution or another filing. Keep notices, delivery evidence, attendance and the signed minutes with the meeting record.","reference":"Sections 117–118 · LODR Regulation 30 · SS-1, paragraph 8"}],"variants":[],"materials":[{"title":"Prior minutes and agenda","detail":"Ask the minutes-book custodian for the last signed minutes and action tracker. Ask each item owner for a decision paper, proposed resolution and disclosure of interests."},{"title":"Obtain the approved decision","detail":"Request a signed minute extract from the minutes-book custodian or compile the eligible directors’ written replies for a circulating resolution. Confirm the date and approved wording before certifying the extract."}],"checks":["Notice and agenda sent in time","Quorum met","Disclosures of interest taken","Resolutions passed and recorded","Minutes circulated and signed","Follow-up filings made in time","Attendance register signed"],"also":["circular-resolution","director-interests","file-mgt-14"]},{"id":"appoint-director","title":"Appoint an additional director","category":"Directors","summary":"Check the Board’s authority, document the appointment and prepare DIR-12.","scope":"Appointment by the Board under section 161(1). An independent director, managing director, nominee or a person resident outside India can trigger further requirements.","related":["act-161","act-152","act-164","act-165","act-170","rule-directors-8","rule-directors-18","lodr-17","lodr-30","rule-directors-14"],"templates":["dir-2","board-notice","resolution-extract"],"steps":[{"title":"Confirm the appointment route","detail":"Identify the enabling article. Check that the proposed director has not previously failed to secure appointment at a general meeting in the circumstances of section 161(1). Record the board-composition checks.","reference":"Sections 149 and 161(1)"},{"title":"Obtain the director’s particulars","detail":"Verify DIN and eligibility, directorship limits, disqualification declarations, written consent and relevant interests. Obtain any nomination and remuneration committee recommendation required for the company.","reference":"Sections 152, 164, 165, 178 and 184 · Directors Rules 8 and 14"},{"title":"Approve the appointment","detail":"Place the candidate’s particulars and effective date before the Board. Record the decision and issue the appointment communication. Diary the earlier of the next AGM and the last date on which it should have been held.","reference":"Section 161(1) · SS-1"},{"title":"File the company’s return","detail":"File DIR-12 within 30 days of appointment. Enter the director’s details, complete the webform consent and declaration with the corresponding DSC and supply the documents required for the chosen designation. Retain the SRN and outcome.","reference":"Sections 152(5) and 170(2) · Directors Rules 8 and 18"},{"title":"Update records and calendar","detail":"Update the directors and KMP register. If continued service is proposed, prepare the members’ appointment process in time. Check eligibility for any exemption from the section 160 notice and deposit requirements.","reference":"Sections 152, 160, 161 and 170"},{"title":"Complete listed-company disclosures","detail":"If applicable, disclose the appointment to the exchanges and check the shareholder approval deadline in Regulation 17(1C), including its exceptions. Use the earliest applicable approval date in the calendar.","reference":"LODR Regulations 17(1C) and 30 · Schedule III, Part A"}],"variants":[],"materials":[{"title":"Candidate and constitutional records","detail":"Request the DIN, signed consent, declarations, specimen signature and directorship list from the proposed director. Obtain the current articles from the company secretary and mark the enabling clause."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find DIR-12. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Enabling clause and eligibility verified","Consent and declarations obtained","Board decision documented","DIR-12 and company register updated","Member approval and exchange deadlines calendared"],"also":["director-appointments","director-interests"]},{"id":"director-interests","title":"Record directors’ disclosures of interest","category":"Directors","summary":"Collect MBP-1, note changes at the Board and retain the disclosure with the company records.","scope":"General notices under section 184(1). Review each proposed contract separately for transaction-specific interests, participation restrictions and applicable exemptions.","related":["act-184","act-189","rule-board-9","lodr-23"],"templates":["mbp-1"],"steps":[{"title":"Identify the relevant meeting","detail":"Collect the notice for the first Board meeting in which a director participates, the first Board meeting of each financial year, and the first Board meeting after a disclosed interest changes.","reference":"Section 184(1)"},{"title":"Complete the notice","detail":"Have each director identify interests in bodies corporate, firms and other associations, with the nature of the interest and shareholding details. Review the dated, signed MBP-1 against the director’s own information.","reference":"Board Powers Rule 9(1) · Form MBP-1"},{"title":"Place the notice before the Board","detail":"Include the disclosure in the meeting papers and minute that the Board took note. Match the interests to each contract on the agenda and record any disclosure of a specific interest and resulting participation decision.","reference":"Section 184(1)–(2) · Board Powers Rule 9(2)"},{"title":"Maintain the disclosure file","detail":"Keep notices at the registered office for eight years from the end of the relevant financial year, with the company secretary or another Board-authorised custodian. Update the register of contracts where section 189 applies.","reference":"Board Powers Rule 9(3) · Section 189"}],"variants":[],"materials":[{"title":"Disclosure particulars","detail":"Give each director the MBP-1 draft from Documents. Request an entity-by-entity list of interests and changes since the last notice and have the director sign the final notice."},{"title":"Recover a missing disclosure","detail":"Ask the director for a freshly signed notice bearing the actual signing date. Record receipt and any late disclosure separately and have the Board note the notice at the appropriate meeting."}],"checks":["Trigger and meeting date identified","Signed MBP-1 received","Board noting recorded","Retention and custody documented"],"also":["related-party","statutory-registers"]},{"id":"director-resignation","title":"Process a director’s resignation","category":"Directors","summary":"Record receipt, calculate the effective date and report the cessation.","scope":"Voluntary resignation under section 168. Check separate steps for an independent director, a whole-time executive or a resignation that leaves the company without directors.","related":["act-168","act-170","rule-directors-15","rule-directors-16","lodr-17","lodr-30"],"templates":["resolution-extract"],"steps":[{"title":"Log the resignation notice","detail":"Record when the company received the written notice. Compare that date with any effective date specified by the director and enter the later date in the register.","reference":"Section 168(1)–(2)"},{"title":"Note the change and assess board strength","detail":"Place the resignation before the Board for noting. Recalculate minimum directors, quorum and committee composition, including any applicable listed-company vacancy deadlines.","reference":"Sections 149, 168 and 174 · LODR Regulation 17"},{"title":"Report the cessation","detail":"File DIR-12 for the company within 30 days of receipt of notice under rule 15, with the resignation notice and evidence requested for this cessation. The director may separately use DIR-11. Save the submitted form and acknowledgement.","reference":"Section 168 · Directors Rules 15–16"},{"title":"Update the public and statutory records","detail":"Update the section 170 register, post resignation information on the company website if it has one, and include the resignation in the directors’ report laid at the immediately following general meeting.","reference":"Sections 168 and 170 · Directors Rule 15"},{"title":"Handle exchange disclosure","detail":"For a listed entity, classify the cessation under Schedule III and file the prescribed particulars on the applicable clock. Review the additional material required where an independent director resigns.","reference":"LODR Regulation 30 · Schedule III, Part A"}],"variants":[],"materials":[{"title":"Notice and evidence of receipt","detail":"Ask the director for the signed resignation, including the intended effective date. Preserve the incoming email with headers or a date-stamped physical acknowledgement. Request a copy from the incoming correspondence register if needed."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find DIR-12 for the company, or DIR-11 for the outgoing director’s optional return. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Receipt and effective date recorded","Board and committee vacancies assessed","DIR-12 acknowledged","Register, report and applicable disclosures updated"],"also":["remove-director","material-event"]},{"id":"registered-office","title":"Move the registered office within local limits","category":"ROC filings","summary":"Document a local move, prepare the address evidence and file INC-22.","scope":"Existing company moving within the local limits of the same city, town or village, under the same Registrar and in the same State. A move outside these boundaries requires a separate approvals analysis.","related":["act-12","rule-incorporation-25","rule-incorporation-27"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Confirm the route and effective date","detail":"Compare the existing and proposed addresses, municipal limits and Registrar jurisdiction. Keep the premises details and internal approval with the proposed date on which the new office can receive communications.","reference":"Section 12(1), (4) and (5)"},{"title":"Authorise the move","detail":"Place the address and effective date before the Board. Record authority to sign and submit INC-22, arrange the premises and update the company’s communications.","reference":"Section 12 · Articles and Board authority"},{"title":"Assemble the address evidence","detail":"Collect the appropriate ownership, lease or authorisation evidence and a utility bill for the premises no older than two months. Check rent receipts, proof of permission and location coordinates against the applicable case in the webform.","reference":"Incorporation Rules 25 and 27 · INC-22"},{"title":"File INC-22","detail":"Submit the notice to the Registrar within 30 days of the change. Reconcile the new address, date and coordinates with the evidence. Save the SRN, fee acknowledgement and final status.","reference":"Section 12(4) · Incorporation Rule 27"},{"title":"Update signage and correspondence","detail":"Arrange delivery of official correspondence, update nameboards, letterheads, notices and website contact details, and verify the new address in MCA master data after processing.","reference":"Section 12(1) and (3)"}],"variants":[],"materials":[{"title":"Premises evidence","detail":"Ask the owner or landlord for the title or lease, occupancy permission and recent utility bill showing the exact address. Have the company’s representative confirm the coordinates and reconcile them to the premises."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find INC-22. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Existing and proposed addresses verified","Approval and occupancy evidence obtained","INC-22 acknowledged","Signage, contacts and master data updated"],"also":["office-routes","file-mgt-14"]},{"id":"file-mgt-14","title":"File a resolution in MGT-14","category":"ROC filings","summary":"Classify the resolution, prepare the certified record and verify the filing.","scope":"Resolutions and agreements covered by section 117(3). Check the company class, transaction-specific provision and applicable exemption before opening a filing.","related":["act-117","act-179","act-102","rule-management-24"],"templates":["resolution-extract"],"steps":[{"title":"Identify the filing provision","detail":"Read the operative resolution or agreement against section 117(3). Record the clause relied on. For a Board resolution under section 179(3), test section 117(3)(g), any company-class exemption and its conditions.","reference":"Sections 117(3) and 179(3)"},{"title":"Calculate the due date","detail":"Count 30 days from passing the resolution or making the agreement. Record the actual meeting or agreement date and allocate a signatory and a reviewer.","reference":"Section 117(1)"},{"title":"Prepare the filing set","detail":"Obtain the certified resolution or agreement and any explanatory statement annexed to the notice. Add the altered constitutional documents or linked forms when the transaction and portal require them.","reference":"Section 117(1) · Management and Administration Rule 24"},{"title":"Complete and reconcile the form","detail":"Enter CIN, purpose, date and resolution particulars. Compare the final text and attachment set with the signed decision, confirm signing authority, then submit the webform and pay the applicable fee.","reference":"Management and Administration Rule 24"},{"title":"Record the outcome","detail":"Save the submitted form, acknowledgement and SRN. Check status or a resubmission request and carry the SRN into any dependent filing.","reference":"Form MGT-14"}],"variants":[],"materials":[{"title":"Certified text and explanatory statement","detail":"Obtain the resolution, accompanying notice and explanatory statement from the meeting custodian. Ask an authorised signatory to certify the exact text adopted and compare it to the signed minute entry."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MGT-14. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Filing trigger and deadline recorded","Certified, signed evidence ready","Form and fee submitted","SRN, final status and dependent filings recorded"],"also":["board-meeting","postal-ballot"]},{"id":"annual-general-meeting","title":"Conduct an annual general meeting","category":"Member meetings","summary":"Set the AGM timetable, issue notice, record voting and identify follow-on filings.","scope":"Ordinary AGM of a company required to hold one. Check special company regimes, class notifications and any current MCA circular governing electronic meetings or filing extensions.","related":["act-96","act-101","act-102","act-103","act-105","act-108","act-118","act-121","lodr-44","act-134","act-91","act-123","act-139","act-148","act-173","act-136","act-107","act-152","act-117","act-137","act-92","lodr-29","lodr-30","rule-management-20"],"templates":["mgt-11"],"steps":[{"title":"Determine the meeting window","detail":"For the first AGM, test nine months from the end of the first financial year. For a later AGM, check six months from year-end and the 15-month interval. Consider a granted Registrar extension and any shorter listed-entity deadline.","reference":"Section 96 · LODR Regulation 44(5)"},{"title":"Approve the meeting papers","detail":"Set the date, venue or permitted electronic mode, business and voting arrangements. Obtain the approved financial statements, reports, proposed resolutions and explanatory statements for special business.","reference":"Sections 96, 102, 129 and 134 · SS-2"},{"title":"Issue the notice","detail":"Ordinarily allow 21 clear days. Check the articles and any applicable class exemption. If using shorter notice for the AGM, obtain the required consent from at least 95% of members entitled to vote, and separately test circulation of financial statements.","reference":"Sections 101 and 136 · SS-2"},{"title":"Arrange voting and representation","detail":"Check member entitlement, proxies or corporate representatives as applicable to the meeting mode, quorum, e-voting and scrutiniser arrangements. For an eligible physical meeting, supply the prescribed proxy form where required.","reference":"Sections 103, 105, 108 and 113 · LODR Regulation 44"},{"title":"Document proceedings and results","detail":"Record the chair, quorum, business, voting and declared results. Enter minutes within 30 days. For listed entities, check exchange reporting of proceedings and voting results on their respective clocks.","reference":"Section 118 · SS-2 · LODR Regulations 30 and 44"},{"title":"Calendar the filings","detail":"Identify resolutions requiring MGT-14. If the company is a listed public company, assess the AGM report under section 121 and MGT-15. For annual accounts and the annual return, select the applicable forms, statutory dates and current circulars.","reference":"Sections 92, 117, 121 and 137"}],"variants":["First AGM","Subsequent AGM"],"materials":[{"title":"Member and annual-report papers","detail":"Ask the RTA or register custodian for the dispatch and voting lists. Obtain the signed accounts and reports from finance and the auditors, and a written timetable from the voting service provider if used."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MGT-15 for a listed public company’s AGM report, and any required MGT-14. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Accounts and reports signed","Member list and voting cutoff reconciled","Agenda and explanatory statements approved","Notice and annual report dispatched","Representation, quorum and voting evidence retained","Minutes and any scrutiniser report complete","Applicable AOC-4, annual return, resolution, auditor and AGM reporting scheduled"],"also":["annual-filing","appoint-auditor","egm"]},{"id":"circular-resolution","title":"Pass a Board resolution by circulation","category":"Board governance","summary":"Decide whether circulation is available, collect directors’ responses and record the result.","scope":"Board or committee business eligible for circulation. Check the Act, Rules, articles and matters reserved for a meeting before selecting this procedure.","related":["act-175","act-179","act-118","rule-board-5"],"templates":["resolution-extract"],"steps":[{"title":"Classify the item","detail":"Check whether the decision must be taken at a meeting, including matters reserved under section 179(3), the Rules and SS-1. Have the authorised person decide to proceed by circulation.","reference":"Sections 175 and 179(3) · SS-1, paragraph 6 and Annexure A"},{"title":"Circulate to every director","detail":"Send the proposed resolution, explanation, supporting papers and voting instructions to all Board or committee members, including interested directors. Identify ineligible voters and keep dispatch evidence.","reference":"Section 175(1) · SS-1, paragraph 6.2"},{"title":"Track votes and meeting requests","detail":"Specify the response period under SS-1, normally no more than seven days plus any applicable postal service time. If at least one-third of the total directors require a Board meeting, refer the matter to a meeting.","reference":"Section 175(1) proviso · SS-1, paragraphs 6.2–6.3"},{"title":"Record the decision","detail":"Verify a majority of directors entitled to vote, account for any higher threshold and determine the passing date under SS-1. Retain the replies, including dissents. At the next Board or committee meeting, note the resolution and enter it in the minutes.","reference":"Section 175(1)–(2) · SS-1, paragraphs 6.3–6.4"}],"variants":[],"materials":[{"title":"Board distribution list and replies","detail":"Ask the company secretary for current director addresses, interests and the articles. Save a copy of each dispatch, delivery confirmation and written vote with its time of receipt."},{"title":"Obtain the approved decision","detail":"Request a signed minute extract from the minutes-book custodian or compile the eligible directors’ written replies for a circulating resolution. Confirm the date and approved wording before certifying the extract."}],"checks":["Meeting-only matters screened out","All directors served","Majority and meeting requests checked","Resolution noted at the following meeting"],"also":["board-meeting"]},{"id":"material-event","title":"Disclose a material event to the exchanges","category":"Listed companies","summary":"Classify a Schedule III event, set the reporting time and retain the exchange evidence.","scope":"Listed entities to which Regulation 30 applies. Debt-only listings have a separate event-reporting framework, including Regulation 51 and the applicable part of Schedule III.","related":["lodr-30","lodr-SIII","lodr-46","lodr-51"],"templates":[],"steps":[{"title":"Capture the trigger","detail":"Log the event, how it came to the entity’s attention, occurrence time, responsible business owner and any Board decision time. Notify the KMP authorised to assess materiality and make disclosures.","reference":"LODR Regulation 30(5)–(6)"},{"title":"Classify the event","detail":"Check Part A of Schedule III. Paragraph A identifies deemed-material items, while paragraph B calls for a documented materiality assessment. Check subsidiary events and any event-specific disclosure particulars.","reference":"LODR Regulation 30(2)–(4), (9) · Schedule III, Part A"},{"title":"Set the applicable clock","detail":"Check the event-specific timeline first. Under the general rule, distinguish Board decisions from events originating inside the entity (12 hours) and outside it (24 hours). For Board decisions, check the 30-minute rule and after-hours proviso against the actual closing time.","reference":"LODR Regulation 30(6) · Schedule III, Part A"},{"title":"Submit and retain the acknowledgement","detail":"Use the exchange announcement format and applicable SEBI particulars. Disclose as soon as reasonably possible. If late, include the reason. Retain the announcement, timestamps and acknowledgements from each relevant exchange.","reference":"LODR Regulation 30(6)"},{"title":"Publish and follow up","detail":"Publish the disclosure on the company website and retain it there for at least five years, then follow the archival policy. Track material developments through the event’s resolution or closure.","reference":"LODR Regulation 30(7)–(8)"}],"variants":[],"materials":[{"title":"Facts and exchange acknowledgement","detail":"Ask the business head for the event record with the exact occurrence and awareness times, and legal or finance for supporting evidence. After filing, retrieve the exchange-stamped acknowledgement and match it to the published announcement."},{"title":"Obtain the filing record","detail":"In the issuer’s exchange filing account, select the applicable event category and obtain its reporting fields. After submission, use the issuer’s announcements history to obtain a timestamped copy and retain it with the internal assessment."}],"checks":["Occurrence and escalation times logged","Event and filing clock classified","Exchange timestamps retained","Website and subsequent updates reconciled"],"also":["board-meeting","director-resignation"]},{"id":"related-party","title":"Review and approve a related party transaction","category":"Board governance","summary":"Test the relationship, document pricing and obtain approvals before contracting.","scope":"Indian companies considering a contract with a related party. Apply the SEBI layer only where the relevant listing provisions govern the entity or its subsidiary.","related":["act-177","act-184","act-188","act-189","rule-board-15","lodr-23","act-2","act-134"],"templates":["mbp-1","board-notice","resolution-extract"],"steps":[{"title":"Identify the parties and transaction","detail":"Map ownership, control, directorships and relationships against the Companies Act and applicable LODR definitions. Identify which group entity is entering the contract, its value, duration and earlier transactions with the party.","reference":"Section 2(76) · LODR Regulation 2(1)(zb)–(zc)"},{"title":"Document the statutory tests","detail":"Identify the relevant section 188 category. Keep separate evidence of ordinary course of business and arm’s-length pricing. Assess section 177 committee approval independently and calculate rule 15 thresholds using the prescribed financial base.","reference":"Sections 177(4)(iv) and 188(1) · Board Powers Rule 15"},{"title":"Complete the listed-company analysis","detail":"Where Regulation 23 applies, assess the listed entity and subsidiary tests, current materiality thresholds, specific exceptions and modifications. Determine whether independent audit committee members and shareholders must approve in advance.","reference":"LODR Regulation 23 · Schedule XII"},{"title":"Prepare and obtain the approvals","detail":"Set out the relationship, valuation, commercial rationale, amount and material terms in the papers. Obtain each applicable prior approval, identify voting restrictions and record interested directors’ participation or abstention.","reference":"Sections 177, 184 and 188 · Board Powers Rule 15 · LODR Regulation 23"},{"title":"Update records and monitor changes","detail":"Complete the statutory register and Board’s report disclosures where required. Calendar periodic listed-entity disclosures, compare actual usage with the approval and refer material changes for review before implementation.","reference":"Sections 188(2) and 189 · LODR Regulation 23(2), (4) and (9)"}],"variants":["Companies Act approval","Listed entity and subsidiary approvals"],"materials":[{"title":"Relationship and price evidence","detail":"Request the group structure and director disclosures from the secretarial team, annual transaction totals from finance and comparable quotations or a valuation from procurement. Record the source date and entity for each figure."},{"title":"Obtain the approved decision","detail":"Request a signed minute extract from the minutes-book custodian or compile the eligible directors’ written replies for a circulating resolution. Confirm the date and approved wording before certifying the extract."}],"checks":["Related party list updated","Arm's length and ordinary course tested","Audit committee approval","Board approval","Members' approval if needed","Register of contracts updated","Disclosure in the board's report"],"also":["director-interests","committees"]},{"id":"incorporation","title":"Incorporate a company","category":"Incorporation","summary":"From name approval to the certificate of incorporation, then the first Board meeting and the filings that follow in the first months.","scope":"Private company incorporation through SPICe+. Also check the constitution-specific requirements below for public, One Person and section 8 companies.","related":["act-153","act-154","act-4","act-3","act-5","act-7","act-9","act-12","act-173","act-184","act-203","act-139","act-56","act-10A","rule-incorporation-12","rule-incorporation-38","rule-incorporation-23A"],"templates":["moa-table-a","dir-2","mbp-1","board-notice"],"steps":[{"title":"Identify subscribers and first directors","detail":"Record the proposed type, share structure and promoters. Arrange the signers’ digital signatures, obtain identity and address documents and verify existing DINs. For eligible new directors apply for a DIN in SPICe+.","reference":"Sections 3, 7, 152–154"},{"title":"Reserve the name and draft the constitution","detail":"Check proposed names for confusion with registered companies and trademarks. Apply in SPICe+ Part A. Finalise the objects, liability, subscriber and capital clauses and the articles.","reference":"Sections 4–5"},{"title":"Choose the incorporation pack","detail":"For an OPC obtain the nominee’s consent and particulars. A public company needs its minimum subscribers and directors. A new section 8 company uses the incorporation and licensing route in SPICe+, with charitable objects and the applicable linked documents.","reference":"Sections 3, 7–8 and 149"},{"title":"Sign and submit the application","detail":"Complete Part B with registered office, capital and director details. Complete the applicable e-MOA, e-AOA, declarations and AGILE-PRO-S linked forms. Obtain authenticated or apostilled documents where the subscriber’s circumstances require them.","reference":"Section 7 · Incorporation Rules"},{"title":"Open the permanent record","detail":"Save the certificate, CIN, PAN and TAN allotment details and stamped constitutional documents. If the registered office differs from the correspondence address at incorporation, arrange INC-22 within the applicable period. Display the name and office address and revise stationery.","reference":"Sections 9 and 12"},{"title":"Organise the first Board meeting","detail":"Diarise the meeting and first auditor appointment. Take note of the constitution, directors, interests, registered office and initial registers. Approve banking authorities and record statutory and operational responsibilities.","reference":"Sections 139, 173 and 184"},{"title":"Complete subscriptions and commencement","detail":"Reconcile subscriber payments with the bank. Where section 10A applies, complete INC-20A within 180 days of incorporation before commencing business or exercising borrowing powers. Deliver certificates or complete the lawful demat route and enter the holders in the register.","reference":"Sections 10A, 56 and 88"}],"materials":[{"title":"Subscribers and registered office","detail":"Send each promoter a list of ID, address, occupation, DIN and subscription details. Obtain premises authorisation and a utility statement from the owner and arrange licensed digital signatures for the people signing."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find SPICe+ Part A, Part B and linked forms. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Subscriber and director identities, signatures and DIN details checked","Name reservation valid","MOA, AOA and incorporation pack signed","Premises occupancy and utility evidence ready","Fees and stamp duty reconciled","Certificate, CIN, PAN and TAN saved","First auditor and Board approvals recorded","MBP-1 collected at the relevant meeting","Bank account and subscriptions reconciled","Signage, correspondence and initial registers updated","Permitted certificates or demat credits completed","Section 10A and other initial filings assessed and completed where applicable"],"variants":["Incorporation of Private Limited Company","Incorporation of One Person Company","Incorporation of Public Limited Company","Incorporation of Section 8 Company (Charitable)"],"also":["board-meeting","appoint-auditor"]},{"id":"office-routes","title":"Choose the route for a registered office move","category":"ROC filings","summary":"The route depends on where the office moves: within the same city, elsewhere in the State, to another Registrar's area in the same State, or to another State.","scope":"For changing the registered office, first compare local limits, Registrar jurisdiction and state boundaries.","related":["act-12","act-13","act-101","act-102","act-110","act-94","lodr-30","rule-incorporation-25","rule-incorporation-27","rule-incorporation-28","rule-incorporation-30"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Document both addresses","detail":"Record the town or village, district, state, Registrar and actual move date. Collect occupancy evidence and confirm the office can receive communications.","reference":"Section 12"},{"title":"Move within the same local limits","detail":"Record the decision and file INC-22 within 30 days of the change. Use the dedicated local move checklist for the premises evidence and updates.","reference":"Section 12(4) · Incorporation Rule 27"},{"title":"Move outside local limits with the same Registrar","detail":"Obtain the required special resolution, file MGT-14 and give the Registrar the new address in INC-22. Calculate the resolution and address deadlines separately.","reference":"Sections 12(4)–(5) and 117"},{"title":"Change Registrar within a state","detail":"Prepare the members’ special resolution and the INC-23 application for Regional Director confirmation. After approval, file the order and address particulars in the sequence and time required for that route.","reference":"Section 12(5)–(7) · Incorporation Rule 28"},{"title":"Move to another state","detail":"Alter the state clause by special resolution. Prepare the creditor and notice papers, advertisements and application for approval. File the certified order with the registrars concerned and obtain the new registration certificate.","reference":"Section 13(4)–(7) · Incorporation Rules 30–31"},{"title":"Update records and correspondents","detail":"Update stationery, signage, banks, licences, taxes, customers and statutory records. Handle a change in the place of keeping member registers separately under section 94.","reference":"Sections 12 and 94"}],"materials":[{"title":"Jurisdiction and occupancy file","detail":"Obtain both addresses from the registered office file. Check the Registrar jurisdiction for each PIN, ask the owner for permission and documentary proof and obtain a signed creditor list for a state-change application where required."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find INC-22, or INC-23 and INC-28 on a route requiring an order. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Local limits, state and Registrar identified","Board and any member approval recorded","Premises verified","Creditor notices, publications and approval obtained where applicable","Required order, resolution and address forms filed","Nameboards, correspondence and external registrations updated"],"variants":["Within local limits","Outside local limits, same Registrar","Change of Registrar in the same state","Move to another state"],"also":["registered-office","file-mgt-14"]},{"id":"committees","title":"Run a Board committee meeting","category":"Board governance","summary":"Prepare the charter, papers and approvals for an Audit, Nomination and Remuneration, or CSR Committee meeting.","scope":"Apply the company’s thresholds, listing category, terms of reference and committee composition requirements.","related":["act-177","act-139","act-144","act-186","act-188","act-178","act-54","act-62","act-135","act-118","lodr-18","lodr-19","rule-board-6"],"templates":["mbp-1","resolution-extract"],"steps":[{"title":"Check constitution and quorum","detail":"Reconcile appointment resolutions and current membership with the committee charter. Identify the required chair, participation of independent directors and quorum for each item.","reference":"Sections 177–178 · LODR Regulations 18–19"},{"title":"Prepare the Audit Committee papers","detail":"Obtain audit issues and the financial statements, controls findings, auditor proposals and any proposed related party transactions. Mark which items need approval and which require a recommendation to the Board.","reference":"Section 177 · LODR Regulation 18"},{"title":"Prepare nomination and remuneration business","detail":"Collect candidate profiles, independence evidence, remuneration comparisons and the proposed terms. Document reasons for the committee’s recommendation and any interests.","reference":"Section 178 · LODR Regulation 19"},{"title":"Consider CSR committee business","detail":"If a CSR committee is required, review the annual plan, budgets and utilisation evidence. Identify any decisions reserved for the Board.","reference":"Section 135 · CSR Rules"},{"title":"Close the meeting record","detail":"Circulate notices and supporting papers, record attendance and quorum, minute the outcomes, and deliver the committee’s recommendations and action list to the Board.","reference":"Section 118 · SS-1"}],"materials":[{"title":"Committee charter and papers","detail":"Request the constituting resolution, latest membership and attendance from the company secretary. Ask finance, HR or the CSR lead for the papers supporting the agenda and reconcile them with the charter."},{"title":"Obtain the approved decision","detail":"Request a signed minute extract from the minutes-book custodian or compile the eligible directors’ written replies for a circulating resolution. Confirm the date and approved wording before certifying the extract."}],"checks":["Committee constituted with the required members","Notice and agenda sent","Quorum met","Recommendations minuted","Placed before the Board"],"variants":[],"also":["board-meeting","related-party","csr"]},{"id":"egm","title":"Convene an extraordinary general meeting","category":"Member meetings","summary":"A general meeting held outside the yearly AGM, called by the board or on a requisition by members.","scope":"For members’ business before the AGM, including a qualifying requisition by members.","related":["act-100","act-102","act-173","act-101","act-103","act-107","act-108","act-117","act-118","lodr-44","rule-management-17"],"templates":["mgt-11","resolution-extract"],"steps":[{"title":"Identify the calling authority","detail":"Document the Board decision or check the validity of the members’ requisition. Record receipt and the statutory time for the Board to act and the meeting to be held. Address a requisitionists’ meeting separately if the Board does not act.","reference":"Section 100"},{"title":"Approve the notice","detail":"Prepare the text of each resolution, explanatory statement and evidence of the interests of directors, KMP and relatives. Fix venue or permitted electronic mode, time, voting arrangements and signing authority.","reference":"Sections 101–102"},{"title":"Send the meeting papers","detail":"Circulate to the members, directors and auditors. Count clear days, service time and any applicable shorter-notice consent. Confirm proxy and e-voting requirements for the chosen mode.","reference":"Sections 101, 105 and 108 · SS-2"},{"title":"Take and record the vote","detail":"Verify authority to attend, quorum and required majority. Record the result of each item with the scrutiniser’s report where relevant and complete the minutes.","reference":"Sections 103–109, 114 and 118"},{"title":"File and notify","detail":"Identify decisions requiring MGT-14, procure a certified copy and record the filing outcome. For a listed entity assess exchange reporting of proceedings and voting results.","reference":"Section 117 · LODR Regulations 30 and 44"}],"materials":[{"title":"Requisition or Board authority","detail":"Obtain the signed requisition or Board resolution, check members’ holdings against the register on the relevant date, and request evidence for the explanatory statement from the transaction owner."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MGT-14 for a registrable decision. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Board approval of the notice","Explanatory statement attached","Notice sent in time","Quorum and proxies checked","Voting recorded","Minutes signed","MGT-14 filed"],"variants":["Board-called EGM","Requisition by members"],"also":["annual-general-meeting","file-mgt-14"]},{"id":"director-appointments","title":"Select the director appointment route","category":"Directors","summary":"Consent, disclosures, approval by the board and members, and the filing with the Registrar.","scope":"For member appointments and Board appointments as alternate, nominee, additional or casual-vacancy director.","related":["act-164","act-165","act-152","act-184","act-161","act-149","act-150","act-160","act-170","lodr-17","lodr-30","rule-directors-8","rule-directors-18"],"templates":["dir-2","mbp-1"],"steps":[{"title":"Select the enabling provision","detail":"Read the articles, nomination instrument and Board composition. Identify whether the appointment belongs to members or a specific section 161 Board power. Record the predecessor and terms where filling a vacancy.","reference":"Sections 149, 152 and 161"},{"title":"Verify eligibility","detail":"Obtain the candidate’s DIN, directorship list and documents establishing consent, qualification and disclosures. Apply independence and nomination committee tests when relevant.","reference":"Sections 149–152, 164–165, 178 and 184"},{"title":"Arrange the proper approvals","detail":"For an additional director, confirm authority in the articles and the end of the term. For an alternate, nominee or casual vacancy check all conditions for that category, including any subsequent member approval. Prepare a separate motion for each director where required.","reference":"Sections 152, 160–162"},{"title":"Set the terms and make the return","detail":"Give the appointment letter, complete DIR-12 with the appropriate event, DSC and supporting papers, and update the directors and KMP register. Record the SRN and future retirement or approval date.","reference":"Sections 152 and 170"},{"title":"Complete the listed-company checks","detail":"Test Board and committee composition, prescribed shareholder approval timing and event disclosure requirements. Add the appointment to the next corporate governance reporting cycle.","reference":"LODR Regulations 17 and 30"}],"materials":[{"title":"Eligibility and nomination papers","detail":"Ask the candidate for a current DIN, consent, disclosures and particulars of other offices. Obtain the articles, nomination instrument or outgoing director’s details for the appointment category."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find DIR-12. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["DIN available","Consent in the form required","Non-disqualification declaration received","Disclosure of interest taken","Board resolution passed","Members' resolution passed where needed","DIR-12 filed in time","Registers updated"],"variants":["Member appointment","Additional director","Alternate director","Nominee director","Casual vacancy","Independent director"],"also":["appoint-director","independent-director"]},{"id":"remove-director","title":"Handle removal or resignation of a director","category":"Directors","summary":"Follow the correct notice, hearing and filing requirements for a removal or a voluntary resignation.","scope":"Removal by members and voluntary resignation have different effective dates and approval requirements. Identify which event occurred before preparing a resolution.","related":["act-169","act-115","act-101","act-102","act-168","act-170","lodr-30","rule-directors-15"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Classify the event","detail":"For a voluntary resignation, date-stamp the written notice and calculate the later of receipt and the effective date stated. For proposed removal, check statutory exclusions and who is entitled to give special notice.","reference":"Sections 115, 168 and 169"},{"title":"Serve notice for a removal","detail":"Validate special notice, send a copy to the director and arrange notice to members. Address any written representation and allow the director an opportunity to be heard.","reference":"Section 169"},{"title":"Obtain the correct decision","detail":"For removal, ascertain the resolution and majority required, including the reappointed independent-director rule. For resignation, the Board notes receipt, effective date and any vacancy to be filled.","reference":"Sections 149, 168 and 169"},{"title":"File and disclose the change","detail":"Use DIR-12, update the register and check Board and committee strength. Record receipt and web filing. For a resignation address the directors’ report and company website, and for a listed entity assess Schedule III.","reference":"Sections 168–170 · LODR Regulation 30"}],"materials":[{"title":"Notice and Board records","detail":"For removal, collect the member’s notice and evidence of holding, and the director’s representation. For resignation, obtain the original notice and record when the company received it."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find DIR-12. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Notice or resignation letter received","Board resolution passed","General meeting resolution passed (removal)","DIR-12 filed in time","Registers updated","Exchange informed if listed"],"variants":["Removal by members","Voluntary resignation"],"also":["director-resignation","material-event"]},{"id":"remuneration","title":"Appoint or remunerate managerial personnel","category":"Directors","summary":"Appointment of a managing or whole-time director and approval of remuneration within or above the limits.","scope":"MD, whole-time director or manager appointments. Apply public/private company distinctions, relevant exemptions and listed-company conditions.","related":["act-196","act-197","act-203","act-178","act-198","act-188","lodr-17","lodr-19","rule-managerial-3","lodr-30"],"templates":["resolution-extract"],"steps":[{"title":"Prepare the terms","detail":"Verify age, eligibility, office, period, remuneration, responsibilities and existing interests. Obtain any nomination and remuneration committee recommendation.","reference":"Sections 178, 196 and 203"},{"title":"Compute the approval requirements","detail":"For companies subject to section 197, calculate profits and remuneration, identify inadequate profits and Schedule V conditions. Check creditor approval for defaults and any government approval or special resolution actually triggered.","reference":"Sections 196–198 · Schedule V"},{"title":"Secure approvals and issue the agreement","detail":"Put the proposal and necessary disclosures before the Board and members as applicable. Record the decision, appointment letter or service agreement, effective date and any conditions.","reference":"Sections 190 and 196–197"},{"title":"Make returns and disclosures","detail":"Identify DIR-12, MR-1 and MGT-14 for the particular event and company class. Where listed, assess remuneration, composition and announcement requirements. Retain consents and SRNs.","reference":"Sections 117, 170, 196 and 203 · LODR Regulations 17, 19 and 30"}],"materials":[{"title":"Proposed terms and profit computation","detail":"Ask HR for the service contract and finance for a section 198 computation. Obtain prior approvals, lender-default status and any creditor consent, then reconcile the proposed payment to those documents."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MR-1 and DIR-12 where applicable. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Eligibility and remuneration computation retained","NRC recommendation obtained where required","Members, creditors or government approvals obtained where triggered","Appointment instrument signed","Applicable returns and disclosures completed"],"variants":[],"also":["director-appointments","committees"]},{"id":"appoint-auditor","title":"Manage the statutory auditor appointment","category":"Audit","summary":"Eligibility, consent, resolution and the filing with the Registrar.","scope":"Separate the first auditor, a regular appointment, government company, casual vacancy, resignation and early removal.","related":["act-139","act-141","act-177","act-140","rule-audit-4","rule-audit-7"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Obtain consent and eligibility evidence","detail":"Request written consent and the auditor’s eligibility certificate. Check independence, limits, rotation and prohibited relationships or services. Identify the appointing authority.","reference":"Sections 139, 141 and 144"},{"title":"Identify the appointment route","detail":"For a non-government company the Board normally appoints its first auditor within 30 days of registration. If it fails, refer the matter to members within the applicable period. Government company appointments follow the CAG route.","reference":"Section 139(5)–(8)"},{"title":"Approve a regular appointment or vacancy","detail":"Take the Audit Committee recommendation where applicable and obtain the required Board or members’ decision. A casual vacancy caused by resignation requires the additional general-meeting approval prescribed for that route.","reference":"Sections 139–142 and 177"},{"title":"Address resignation or removal","detail":"Obtain the outgoing auditor’s resignation statement and assess ADT-3. Removal before expiry requires the prescribed prior government approval and special resolution. Give the auditor the statutory hearing opportunity.","reference":"Section 140 · Audit Rules"},{"title":"Close the appointment record","detail":"Fix remuneration, issue the appointment communication and record the term and meeting. Prepare ADT-1 for the applicable event in the current form and retain its acknowledgement.","reference":"Sections 139 and 142 · Audit Rule 4"}],"materials":[{"title":"Auditor eligibility and predecessor file","detail":"Ask the audit firm for its signed consent, firm registration and eligibility certificate. Obtain the outgoing auditor’s notice, previous appointment date and AGM minutes from the company’s records."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find ADT-1, ADT-2 or ADT-3 for the actual event. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Auditor eligibility and consent received","Statutory appointment route documented","Remuneration set by the appropriate authority","Appointment communicated","Applicable filings acknowledged"],"variants":[],"also":["annual-general-meeting","committees"]},{"id":"allotment","title":"Issue and allot shares","category":"Share capital","summary":"Increase of capital if needed, the offer, the resolutions, the allotment and the returns.","scope":"Rights issues, preferential issues and private placements have different approvals and clocks. Select the route before collecting funds.","related":["act-61","act-64","act-62","act-42","act-179","act-39","act-56","act-88","act-49","act-46","act-55","lodr-30","rule-prospectus-14","rule-share-capital-13"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Check authority and route","detail":"Reconcile authorised, issued and paid-up capital and the articles. For a preferential offer test both section 62 and, where relevant, private-placement rules. Obtain valuation and dematerialisation advice as required.","reference":"Sections 42, 61–64"},{"title":"Approve and issue the offer","detail":"Record Board decisions and applicable shareholder approvals. For a rights issue calculate entitlements and offer terms. For a private placement identify offerees, maintain the offer record and issue the prescribed communication.","reference":"Sections 42 and 62"},{"title":"Reconcile applications and funds","detail":"Match applications with subscribers, bank records and permitted payment channels. Check the separate bank account and use-of-funds restrictions that apply to a private placement.","reference":"Section 42"},{"title":"Approve allotment and report","detail":"Prepare the allottee list and allotment resolution. Set the PAS-3 due date for the route. For a private placement the statutory filing period is 15 days after allotment.","reference":"Sections 39 and 42 · Prospectus and Allotment Rules"},{"title":"Update ownership records","detail":"Complete demat credits or issue certificates when permitted, reconcile quantities with the register, and record private placement offers. Test applicable exchange approvals, disclosures and listing of new securities.","reference":"Sections 46, 56 and 88 · LODR Regulations 28 and 30"}],"materials":[{"title":"Capital, value and subscriptions","detail":"Ask the RTA or register custodian for the capital table, the valuer for a signed report if required, and finance for applicant-level bank credits. Match the allottee list to each offer and receipt."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find PAS-3. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Capital headroom confirmed","Offer route and valuation established","Board and any required member approvals logged","Applicants reconciled to funds","Allotment resolution and return complete","Register and permitted certificate or demat records updated"],"variants":["Rights Issue","Private Placement and Preferential Allotment"],"also":["authorised-capital","book-closure"]},{"id":"bonus-split","title":"Carry out a bonus issue, subdivision or buy-back","category":"Share capital","summary":"Changes to share capital that do not raise fresh money: bonus issue, split of shares and buy-back.","scope":"Choose one capital action and apply its own approval, record-date and filing route.","related":["act-63","act-14","act-61","act-68","act-69","act-70","act-88","lodr-30","rule-share-capital-14","rule-share-capital-17","lodr-42"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Check authority and capital","detail":"Obtain the articles and the latest capital reconciliation. Determine whether authority, reserves, creditor position and any exchange approval support the selected action.","reference":"Sections 61, 63 and 68–70"},{"title":"For a bonus issue","detail":"Verify eligible reserves and statutory preconditions, including fully paid shares. Obtain the Board recommendation and member authority, set the record date, allot and file PAS-3 where applicable.","reference":"Section 63"},{"title":"For subdivision or consolidation","detail":"Review the proposed face value, voting proportions and whether Tribunal approval is triggered. Obtain the appropriate resolution, revise the capital clause and give the Registrar notice of alteration.","reference":"Sections 61 and 64"},{"title":"For a buy-back","detail":"Calculate the limits, solvency and post-buy-back debt ratio, determine the approval threshold and comply with restrictions. Choose the listed or unlisted process, complete the declarations, offer, extinguishment, register and return.","reference":"Sections 68–70"},{"title":"Reconcile the post-action capital","detail":"Compare holder entitlements, depository confirmations and the revised capital register. Keep filings, shareholder communications and any exchange acknowledgements with the corporate-action record.","reference":"Sections 64, 68 and 88 · LODR Regulations 30 and 42"}],"materials":[{"title":"Capital action calculation","detail":"Ask finance for an audited reserves calculation and capital reconciliation. For a buy-back obtain the solvency workpaper and lender position, and for all routes get an entitlement simulation from the RTA."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find PAS-3, SH-7 or the applicable buy-back return. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Constitution and capital checked","Applicable reserves and limits documented","Relevant approvals obtained","Record date, entitlements and allotment or extinguishment reconciled","Solvency file and buy-back return complete where applicable","Registers and applicable filings updated"],"variants":["Buy-Back of Shares","Bonus Issue"],"also":["book-closure","allotment"]},{"id":"esop","title":"Grant employee options or issue sweat equity","category":"Share capital","summary":"Set eligibility and terms, obtain the required approvals, and record grants, allotments and ownership.","scope":"Select the employee stock option or sweat equity route and apply separate SEBI requirements for listed companies.","related":["act-178","act-62","act-54","act-39","rule-share-capital-8","rule-share-capital-12"],"templates":["resolution-extract"],"steps":[{"title":"Design the issue","detail":"Document eligibility, purpose, dilution, vesting, exercise terms and approvals. For sweat equity identify the contribution of know-how, intellectual property or value additions and obtain the required valuation.","reference":"Sections 54 and 62(1)(b)"},{"title":"Prepare approvals","detail":"Put the scheme and disclosures before the appropriate committee and Board. Test the shareholder resolution needed for the company class, grant size and beneficiaries. Check listing requirements where applicable.","reference":"Sections 54, 62 and 178 · Share Capital Rules 8 and 12"},{"title":"Record grants and exercise","detail":"Send individual grant or issue letters, track vesting and lapses and record exercises and funds received. For sweat shares apply lock-in and disclosure rules. Maintain SH-6 or SH-3 for the selected route.","reference":"Share Capital Rules 8 and 12"},{"title":"Allot and reconcile","detail":"Record allotment, file the return of allotment, complete demat credits or permitted certificates, and update capital and member records. Submit the resolution filing where triggered.","reference":"Sections 39, 56, 88 and 117"}],"materials":[{"title":"Grant and valuation file","detail":"Obtain the current scheme and employee eligibility schedule from HR, the valuation from the registered valuer where required and exercise receipts from finance. Reconcile each grant with the cap table."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find PAS-3 for an allotment and MGT-14 where required. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Eligibility, plan and valuation checked","Required committee, Board and member decisions recorded","Register of options or sweat equity updated","Allotment and filing evidence retained"],"variants":["Employee Stock Option Scheme","Issue of Sweat Equity Shares"],"also":["allotment","committees"]},{"id":"dividend","title":"Declare and pay a dividend","category":"Shareholders","summary":"Interim and final dividend, the bank account for it, and transfer of unpaid dividend.","scope":"Final and interim dividends use different approval routes. Test the availability of distributable profits and the rules on reserves.","related":["act-123","act-91","act-127","act-124","act-125","lodr-42","rule-dividend-3"],"templates":["resolution-extract"],"steps":[{"title":"Calculate the amount available","detail":"Obtain the profit and depreciation computation, review losses and arrears, and identify the conditions for using reserves or declaring an interim dividend.","reference":"Section 123 · Dividend Rule 3"},{"title":"Approve the dividend and entitlement date","detail":"The Board recommends a final dividend for members or declares an interim dividend. Record the amount per share, eligibility and payment method. Decide whether a record date or closure is needed.","reference":"Sections 91 and 123 · LODR Regulation 42"},{"title":"Fund and pay","detail":"Deposit the dividend amount into the separate bank account within five days of declaration and arrange payment within 30 days, subject to the statutory exceptions. Reconcile successful and returned payments.","reference":"Sections 123(4) and 127"},{"title":"Manage unclaimed amounts","detail":"Transfer the balance after the payment period to the Unpaid Dividend Account within the next seven days. Publish the required statement, answer claims and track the seven-year IEPF transfer of amounts and the separate test for shares.","reference":"Sections 124–125 · IEPF Rules"}],"materials":[{"title":"Payment and entitlement records","detail":"Ask finance for the distributable surplus and bank reconciliation. Obtain the entitlement file from the RTA or depository and a payment-status file from the bank, then identify unpaid balances."},{"title":"Recover an unpaid payment","detail":"Obtain the rejected or unpresented payment report from the bank, confirm holder particulars with the RTA, and match any claimant request to the unpaid dividend ledger or applicable IEPF claim."}],"checks":["Audited accounts approved","Board resolution on dividend","Register of members closed or record date fixed","AGM resolution (final dividend)","Dividend bank account opened","Dividend paid within the time allowed","Unpaid dividend account maintained","Transfer to IEPF on the due date"],"variants":["Declaration and Payment of Dividend","Transfer of Unpaid Dividend and Shares to IEPF"],"also":["book-closure","annual-general-meeting"]},{"id":"borrowing","title":"Approve borrowing, loans, investments or deposits","category":"Finance","summary":"Board and members' approval of borrowings, security, loans, investments and guarantees, and of deposits.","scope":"Classify each receipt or outflow before applying borrowing, deposit, related-director or intercorporate investment rules.","related":["act-179","act-71","act-180","act-185","act-186","act-187","act-73","act-76","act-77","act-78","lodr-23","rule-deposits-2","rule-deposits-16"],"templates":["resolution-extract"],"steps":[{"title":"Classify the proposal and calculate limits","detail":"Identify the borrower, lender, instrument and security. Reconcile proposed and existing borrowings against paid-up capital, free reserves and securities premium, excluding qualifying temporary loans where applicable.","reference":"Sections 179 and 180"},{"title":"Approve financing and security","detail":"Obtain the applicable Board decision, special resolution and lender consents. Test the undertaking-disposal provision on the actual terms of the security and record why it does or does not apply.","reference":"Sections 179–180"},{"title":"Assess loans, guarantees and investments","detail":"Check section 185 restrictions and section 186 financial limits, interest rate, approvals and disclosures. Record interested parties and maintain the register for relevant transactions.","reference":"Sections 185–187"},{"title":"Test deposit treatment","detail":"Determine whether the receipt is excluded from deposits and obtain evidence for the exclusion. If it is a deposit, check eligibility, member or public route, circular, repayment reserve and reporting requirements before acceptance.","reference":"Sections 73–76 · Deposits Rules"},{"title":"Complete follow-up records","detail":"Sign the facility and security documents, register any charge and assess the appropriate deposit return. Keep calculation workings and payment evidence with Board records.","reference":"Sections 77, 85 and 186"}],"materials":[{"title":"Finance terms and limits","detail":"Ask treasury for outstanding facilities, proposed terms, covenants and recent balance sheet. Obtain director or lender declarations needed to classify receipts and reconcile each existing exposure."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find DPT-3 for applicable receipts or the required charge form. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Financing classified and exclusions documented","Borrowing and investment limits computed","Applicable permissions and lender consents secured","Security, charge and deposit records updated"],"variants":["Acceptance of Deposits by eligible companies","Loans to Directors and Inter-Corporate Loans and Investments"],"also":["charge","related-party"]},{"id":"charge","title":"Register, modify or satisfy a charge","category":"Finance","summary":"Registering a charge on the company's assets with the Registrar, and filing its satisfaction.","scope":"For a security interest created by the company, a modification to its terms or the discharge of the secured debt.","related":["act-179","act-180","act-77","act-78","act-85","act-82","rule-charges-3","rule-charges-8"],"templates":["resolution-extract"],"steps":[{"title":"Confirm authority and transaction","detail":"Match the executed security to the facility, asset descriptions, borrowers, charge holders and ranking. Check Board authority, borrowing limits, the articles and any required member consent.","reference":"Sections 77, 179 and 180"},{"title":"Prepare the right form","detail":"Use CHG-1 for relevant non-debenture charges or CHG-9 for debenture-related charges. Attach the executed instrument, secure the required signatures and calculate the ordinary registration period and any applicable late window from the correct event date.","reference":"Sections 77 and 79 · Charges Rule 3"},{"title":"Check registration","detail":"Save the SRN and registration or modification certificate, compare its particulars to the instrument, enter the charge in the company register and keep a copy of the instrument for inspection.","reference":"Sections 77 and 85"},{"title":"Record satisfaction","detail":"Get a discharge letter from the charge holder, reconcile full satisfaction date, file CHG-4 and update the company’s register after checking the recorded satisfaction.","reference":"Sections 82–85"}],"materials":[{"title":"Executed security or release","detail":"Obtain the signed and stamped security instrument, date of creation, charge-holder details and asset description from the lender or legal team. For satisfaction, request a dated release or no-dues letter and the existing charge ID."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find CHG-1, CHG-9 or CHG-4. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Signed instrument and authority retained","Charge or satisfaction form submitted","Registration or modification evidence saved","Bank release and satisfaction evidence recorded where relevant"],"variants":[],"also":["borrowing"]},{"id":"annual-filing","title":"Complete annual and recurring filings","category":"Annual filings","summary":"The returns a company files every year with the Registrar.","scope":"Use the company type, financial year, AGM details and listing category to set each filing obligation.","related":["act-92","act-137","act-139","act-73","act-153","act-405","act-134","rule-accounts-12","rule-management-11","rule-directors-12A"],"templates":["resolution-extract"],"steps":[{"title":"Reconcile the approved annual pack","detail":"Obtain signed accounts and auditors’ and Board reports. Confirm the AGM date, any adjournment, and whether the statements were adopted. For an OPC, an unheld AGM or a producer company use the relevant statutory route.","reference":"Sections 96, 134 and 137"},{"title":"File the financial statements","detail":"Choose the applicable AOC-4, consolidated, XBRL or sectoral form and linked reports. Calculate the statutory filing date and record any officially notified extension applicable to that year and form.","reference":"Section 137 · Accounts Rule 12"},{"title":"Complete the annual return","detail":"Reconcile members, securities, directors, meetings and turnover with signed registers. Choose MGT-7 or MGT-7A as applicable, obtain certification where required and diary the filing clock based on the AGM or when it should have been held.","reference":"Section 92 · Management and Administration Rules"},{"title":"Review other periodic obligations","detail":"Test ADT-1 on appointment, DPT-3 on applicable receipts and MSME reporting on qualifying overdue amounts. Under the revised DIN KYC cycle effective 31 March 2026 check the director’s last KYC and update triggers before setting the next due date. For a DIN holder who completed KYC before the transition and has no intervening update trigger, the next periodic filing is due by 30 June 2028.","reference":"Sections 73, 139 and 405 · Directors Rule 12A"},{"title":"Close the compliance record","detail":"Store acknowledgements and SRNs against the signed accounts, return and applicable event. Monitor resubmissions and give the Board an exceptions report with owners and dates.","reference":"Sections 92, 134 and 137"}],"materials":[{"title":"Accounts, membership and prior SRNs","detail":"Obtain signed accounts and reports from finance and the auditors. Ask the secretarial custodian for meeting dates, register movements and earlier SRNs. Reconcile opening figures to the prior accepted return."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find the applicable AOC-4 and MGT-7 or MGT-7A variants. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["AOC-4 variant and annual return selected","Signed accounts and AGM date reconciled","Financial statements and MGT-7 or MGT-7A acknowledged","DPT-3, DIN KYC and MSME reporting assessed against actual triggers","Registers and Board status report updated"],"variants":[],"also":["annual-general-meeting","appoint-auditor"]},{"id":"change-name","title":"Change the company name","category":"Constitution","summary":"Name approval, the resolution and the Registrar's fresh certificate.","scope":"For a voluntary name change of an existing company. Distinct routes apply to a government direction and a change arising solely from status conversion.","related":["act-4","act-13","act-14","lodr-30","rule-incorporation-29"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Check and reserve the name","detail":"Approve alternatives, search existing names and trademarks, obtain any required consents and submit the name reservation request for an existing company.","reference":"Sections 4 and 13 · Incorporation Rules"},{"title":"Approve the amendment","detail":"Use the reserved name in the proposed memorandum and consequential articles. Obtain Board and member approval, then file the special resolution in MGT-14.","reference":"Sections 13–14 and 117"},{"title":"Apply for the name change","detail":"Prepare INC-24, state the reason and reconcile it to the name reservation and MGT-14 SRNs. Respond to any requisition. The change takes effect on issue of the fresh certificate.","reference":"Section 13 · Incorporation Rule 29"},{"title":"Update the operating record","detail":"Verify the new certificate and master data. Update tax registrations, licences, banks, stationery and contracts and display former names where section 12 requires it.","reference":"Sections 12–13"}],"materials":[{"title":"Name reservation and approvals","detail":"Ask promoters for proposed names and trademark consent if relevant. Retrieve the approved name reservation and SRN from the applicant’s filing history and compare its validity date with the meeting schedule."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find RUN, MGT-14 and INC-24. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Name reserved","Special resolution passed","MGT-14 filed","INC-24 filed","Fresh certificate received","Authorities informed"],"variants":[],"also":["alter-moa-aoa","file-mgt-14"]},{"id":"alter-moa-aoa","title":"Alter the constitution or convert company status","category":"Constitution","summary":"A special resolution, a filing, and some changes that need extra approval, including conversion between private and public.","scope":"Select the exact clause and statutory conversion route before drafting the resolutions.","related":["act-13","act-14","act-173","act-110","act-2","act-117","act-18","rule-incorporation-6","rule-incorporation-7","rule-incorporation-41"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Identify the clause and the conversion","detail":"Compare the certified current memorandum and articles with the proposed text. Identify any entrenchment, class rights, unutilised public issue proceeds or approvals relevant to an object change.","reference":"Sections 4–5, 13–14 and 48"},{"title":"Choose the route","detail":"Ordinary capital changes can fall under sections 61 and 64. For a public-to-private conversion assess Regional Director approval. For OPC conversions test the distinct INC-6 route and eligibility conditions.","reference":"Sections 13–14, 18, 61 and 64"},{"title":"Approve and notify members","detail":"Take Board approval, then the applicable member decision. Prepare the explanatory statement and consider any postal-ballot, advertisement, exit opportunity or other special requirement for the particular change.","reference":"Sections 13–14, 102 and 110"},{"title":"File and bring into effect","detail":"Submit the appropriate MGT-14, conversion forms, altered documents and any required order. Record when registration, approval or a fresh certificate makes the alteration effective. Replace copies and update records.","reference":"Sections 13–15, 18 and 117"}],"materials":[{"title":"Certified constitution and class rights","detail":"Obtain the last registered memorandum and articles from company records or a certified copy through public document inspection. Compare them with filed amendments and mark each proposed change."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MGT-14 and the applicable conversion or alteration form. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Board approval","Special resolution passed","Altered documents prepared","MGT-14 filed","Order received where required"],"variants":["Conversion of Private Company into Public Company","Conversion of Public Company into Private Company","Conversion of OPC into Private or Public Company","Conversion of Private Company into OPC","Alteration of MOA - Object Clause","Alteration of MOA - Liability Clause","Alteration of MOA - Capital Clause (Increase in Authorised Capital)","Alteration of Articles of Association"],"also":["change-name","authorised-capital"]},{"id":"authorised-capital","title":"Increase authorised share capital","category":"Share capital","summary":"Altering the capital clause and filing the notice.","scope":"For a company limited by shares proposing a higher authorised capital ceiling under section 61.","related":["act-61","act-14","act-173","act-117","act-64","rule-share-capital-15"],"templates":["resolution-extract"],"steps":[{"title":"Reconcile the capital clause","detail":"Compare the memorandum, articles and master data. Check authorisation in the articles and calculate the proposed class, face value, number of shares and resulting ceiling.","reference":"Sections 13–14 and 61"},{"title":"Prepare the resolutions","detail":"If the articles must first be amended, obtain the appropriate special resolution. Arrange the section 61 member resolution and amended memorandum, with the required notice and explanatory statement.","reference":"Sections 61, 101 and 102"},{"title":"File the alteration","detail":"File SH-7 within the applicable period, normally 30 days from the increase. Pay the applicable fees and stamp duty and file any separate registrable resolution. Reconcile approved master data and retain receipts.","reference":"Sections 64 and 117"},{"title":"Update corporate copies","detail":"Mark the operative capital clause in every relevant copy. Before issuing shares, follow the separate offer and allotment procedure applicable to that issue.","reference":"Sections 15, 39 and 62"}],"materials":[{"title":"Capital-clause reconciliation","detail":"Get the registered memorandum and articles from the records custodian. Compare their ceiling with the last accepted SH-7 and MCA master data and ask finance for the applicable fee and stamp duty."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find SH-7. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Articles checked","Board and members' resolutions","SH-7 filed in time","Stamp duty and fees paid","Altered Memorandum filed"],"variants":[],"also":["allotment","alter-moa-aoa"]},{"id":"restructuring","title":"Assess a merger, demerger or disposal","category":"Tribunal matters","summary":"Business restructuring: schemes of arrangement, sale or lease of an undertaking, and spinning off a business.","scope":"Separate a scheme requiring Tribunal sanction, an eligible fast-track merger, and a sale or lease of an undertaking.","related":["act-230","act-232","act-180","act-102","act-231","lodr-37","lodr-30","act-233","rule-arrangements-3"],"templates":["resolution-extract"],"steps":[{"title":"Classify the proposed transaction","detail":"Prepare a before-and-after structure, property and liability schedule, accounting treatment and valuation. For a disposal, test section 180 and any exemption. For a merger identify the normal or eligible fast-track route.","reference":"Sections 180, 230–233"},{"title":"Approve the project and scheme","detail":"Document the commercial rationale, share-exchange ratio where applicable and impact on creditors. Obtain the right Board decisions and check filing with exchanges or SEBI before presenting a listed scheme.","reference":"Sections 230–233 · LODR Regulation 37"},{"title":"Obtain the approvals for that route","detail":"Follow the Tribunal’s directions on notices and meetings, statutory creditor and member majorities, regulatory notices and sanction. For a fast-track case use the section 233 approvals. A direct disposal instead needs approvals under its own route.","reference":"Sections 180, 230, 232–233"},{"title":"Implement and reconcile","detail":"File the certified order or confirmation, check the appointed and effective dates and complete any allotments, transfers and changes to registers and licences. Retain proof of implementation and any continuing scheme returns.","reference":"Sections 231–233 · Arrangements Rules"}],"materials":[{"title":"Scheme and stakeholder evidence","detail":"Request the scheme, valuation, latest accounts and accounting certificate from the transaction advisers. Have finance reconcile creditor lists and the RTA certify the member lists required by the convening order."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find the relevant scheme application and INC-28 for an order that must be registered. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Transaction route and valuations documented","Board approval recorded","Required stakeholder consents, notices or meetings completed","Required regulator, Tribunal or fast-track order received","Order registration and post-effective records checked"],"variants":[],"also":["material-event","file-mgt-14"]},{"id":"strike-off","title":"Apply to strike off a company","category":"Company status","summary":"Applying to the Registrar to remove the name of a company that has no business.","scope":"Voluntary removal of the company’s name under section 248(2). Assess Tribunal winding up or IBC voluntary liquidation separately if strike-off does not fit.","related":["act-248","act-249","act-250","rule-the-companies-removal-of-names-of-companies-from-the-register-of-companies-rules-2016-4"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Verify eligibility","detail":"Identify the statutory ground, confirm the company has extinguished its liabilities and check disqualifications, recent transactions and pending proceedings. Regularise overdue returns required for this application.","reference":"Sections 248–249 · Removal of Names Rules"},{"title":"Secure approvals","detail":"Obtain a special resolution or consent from members holding the prescribed proportion of paid-up share capital. Obtain regulator consent if the company is subject to a special Act and that consent is required.","reference":"Section 248(2)"},{"title":"Prepare the supporting pack","detail":"Ask the accountant for a statement of accounts within the permitted age and the required certification. Obtain each director’s affidavit and indemnity, member authority and any outstanding litigation details.","reference":"Removal of Names Rules · STK-2, STK-3 and STK-4"},{"title":"File and monitor notices","detail":"Submit STK-2 and attachments, retain the service request and monitor public notices, objections and the eventual Gazette notice. Retain the company records and identify surviving obligations.","reference":"Sections 248–250"}],"materials":[{"title":"Closure and no-liability records","detail":"Obtain recent bank closure or balance records, tax position and creditor releases. Ask the accountant for the statement of accounts and directors for signed affidavits, indemnities and details of pending proceedings."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find STK-2. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Ground and section 249 eligibility documented","Liabilities extinguished","Member approval or consent documented","Affidavits, indemnities and accounts certified","STK-2 and public notice status tracked"],"variants":[],"also":["dormant-company","winding-up"]},{"id":"capital-reduction","title":"Reduce share capital","category":"Share capital","summary":"Special resolution, confirmation by the Tribunal and filing of the order with the Registrar.","scope":"For a reduction requiring special resolution and Tribunal confirmation under section 66.","related":["act-66","act-117","rule-nclt-procedure-for-reduction-of-share-capital-of-company-rules-2016-2"],"templates":["resolution-extract"],"steps":[{"title":"Design the reduction","detail":"Reconcile issued capital, class rights, accounting treatment and liability to creditors. Confirm there are no arrears in repayment of deposits or interest thereon.","reference":"Section 66"},{"title":"Approve and file the resolution","detail":"Set out the precise amount and method of reduction, obtain Board and special member resolutions and file MGT-14 within 30 days.","reference":"Sections 66 and 117"},{"title":"Apply to the Tribunal","detail":"Prepare RSC-1, the creditor list, auditor certificates, affidavit and accounting materials. Serve the notices and address objections or consent and security requirements as directed.","reference":"Section 66 · NCLT Reduction Rules 2–5"},{"title":"Register the order","detail":"Obtain the certified confirmation order and approved minute. Deliver them to the Registrar within 30 days of receiving the order and verify the registration certificate. Update the memorandum, capital registers and depository entries.","reference":"Section 66(5) · NCLT Reduction Rule 6"}],"materials":[{"title":"Creditor and accounting certificates","detail":"Ask finance for the dated creditor list and proposed capital minute, and the auditor for the prescribed certificates. Request the certified order from the Tribunal registry after pronouncement."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find INC-28 for the confirmed reduction order. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."},{"title":"Obtain the Tribunal application papers","detail":"Request the RSC-1 filing requirements from the jurisdictional Tribunal registry. Obtain the certified creditor list and prescribed certificates from finance and the auditor before verification of the petition."}],"checks":["Board and Special Resolutions","MGT-14 SRN","auditor-certified list of creditors","auditor certificate","memorandum of reduction","affidavit verifying petition","NCLT order","altered MOA."],"variants":[],"also":["file-mgt-14","authorised-capital"]},{"id":"debentures","title":"Issue debentures and arrange trusteeship","category":"Share capital","summary":"Board and shareholder approvals, the trustee and trust deed, certificates and the register of debenture holders.","scope":"Identify secured, convertible, publicly offered, privately placed or listed securities before designing the issue.","related":["act-42","act-56","act-71","act-88","rule-share-capital-18"],"templates":["resolution-extract"],"steps":[{"title":"Design the instrument","detail":"Confirm the amount, tenure, conversion or redemption terms and security. Apply section 71 with the offer-route requirements and applicable SEBI issue and listing conditions.","reference":"Sections 42, 62 and 71"},{"title":"Approve and appoint the trustee","detail":"Arrange the required Board and member approvals. Where trusteeship is required, obtain the eligible trustee’s written consent before the offer, and draft the security and trust deed.","reference":"Section 71 · Share Capital Rule 18"},{"title":"Make the offer and allot","detail":"Finalise the offer record, reconcile subscriptions and approve allotment. Submit the applicable MGT-14 and PAS-3 and register any security charge under the correct form.","reference":"Sections 39, 42, 71, 77 and 117"},{"title":"Complete issue and ongoing records","detail":"Arrange demat credits or certificate delivery where lawful. Maintain the debenture-holder register, execute the trust deed within the applicable period and diary interest, covenants, reserves and redemption.","reference":"Sections 56, 71 and 88"}],"materials":[{"title":"Security and trustee pack","detail":"Request the term sheet, trustee eligibility and written consent from the arranger, charge particulars from legal and subscriber records from treasury. Reconcile the trust deed with the approved instrument."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find PAS-3 and the applicable charge return. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Board and Special Resolutions","debenture trust deed","trustee consent","instrument creating charge","MGT-14 SRN","PAS-3","register of debenture holders (MGT-2)","credit rating if required."],"variants":[],"also":["charge","allotment"]},{"id":"postal-ballot","title":"Pass a resolution by postal ballot","category":"Member meetings","summary":"Passing a resolution by post or electronic means, with a scrutinizer, and filing the result.","scope":"For a resolution required or permitted by section 110, after testing available general-meeting and e-voting alternatives.","related":["act-110","act-117","act-118","rule-management-20","rule-management-22","lodr-44"],"templates":["resolution-extract"],"steps":[{"title":"Check eligibility and appoint the scrutiniser","detail":"Identify the business and voting threshold, check applicable exceptions, and have the Board approve the notice, timeline, scrutiniser and voting arrangements.","reference":"Section 110 · Management and Administration Rules 20 and 22"},{"title":"Dispatch the ballot notice","detail":"Send the text, reasons, explanatory statement and voting instructions to eligible members. Keep evidence of dispatch and make the required publication and website disclosures.","reference":"Sections 102 and 110 · SS-2"},{"title":"Count votes and declare the outcome","detail":"Have the independent scrutiniser reconcile voting and deliver the report. Announce the outcome, record the effective date and enter the resolution in the minutes book.","reference":"Sections 110 and 118"},{"title":"Report the resolution","detail":"Where section 117 applies, file MGT-14 and the required documents. For a listed entity submit applicable voting results. MGT-15 relates to the AGM report of a listed public company.","reference":"Sections 117 and 121 · LODR Regulation 44"}],"materials":[{"title":"Voting file and scrutiniser report","detail":"Obtain the voting cut-off list from the RTA or register custodian, confirm the e-voting event with the service provider and request the signed report and reconciled vote totals from the scrutiniser."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MGT-14 for a registrable decision. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Board authorisation and scrutiniser appointment recorded","Notice and explanatory statement dispatched","Voting and publication evidence retained","Scrutiniser’s report and declared result recorded","Applicable MGT-14 and exchange filings completed"],"variants":[],"also":["egm","file-mgt-14"]},{"id":"winding-up","title":"Prepare a Tribunal winding-up case","category":"Company status","summary":"Prepare the statutory petition, follow the Tribunal’s directions and track liquidation through dissolution.","scope":"Companies Act winding up by the Tribunal. Establish a statutory ground and eligible petitioner. Handle IBC liquidation and voluntary liquidation under their separate processes.","related":["act-271","act-272","act-275","act-277","act-302","rule-companies-winding-up-rules-2020-3"],"templates":["resolution-extract"],"steps":[{"title":"Check jurisdiction and authority","detail":"Identify the winding-up ground, applicant standing and correct Tribunal bench. Obtain resolutions or approvals and compile the records of assets, liabilities, creditors and pending proceedings.","reference":"Sections 271–274"},{"title":"Prepare and serve the petition","detail":"Select WIN-1 or WIN-2 according to the applicant and attach the applicable verification and statement of affairs. Follow the bench directions on service, advertisement and replies.","reference":"Sections 272–274 · Winding Up Rules"},{"title":"Record the Tribunal’s order","detail":"Obtain the signed order and details of any provisional or company liquidator. Track service and directions using the case number and the order’s operative dates.","reference":"Sections 273, 275 and 277"},{"title":"Support liquidation and dissolution","detail":"Deliver books, assets and information to the liquidator, track claims and accounts, and preserve the final report. Record the dissolution order and filing with the Registrar.","reference":"Sections 281, 283–284 and 302"}],"materials":[{"title":"Petition and financial records","detail":"Ask the authorised petitioner and legal team for the ground, authority and statutory notices. Obtain accounts, creditor details and the current case or order copies from the registry with the case number."},{"title":"Obtain registry documents","detail":"Use the Tribunal case number and bench to request certified copies of orders from the registry. For a new petition, identify the prescribed WIN form and current bench filing requirements before preparing the affidavits."}],"checks":["Statement of affairs","creditor list","audited accounts","WIN-1, WIN-2, WIN-3","NCLT order","liquidator reports","final accounts."],"variants":[],"also":["strike-off"]},{"id":"change-financial-year","title":"Apply for a different financial year","category":"Company administration","summary":"Establish the overseas consolidation requirement, obtain Regional Director approval and register the order.","scope":"For an eligible Indian holding, subsidiary or associate of a company incorporated outside India that must follow another financial year for consolidation.","related":["act-2","rule-incorporation-40"],"templates":["resolution-extract"],"steps":[{"title":"Establish the need for consolidation","detail":"Obtain the group chart and confirmation of the foreign entity’s accounting year and consolidation requirement. Map the present and requested Indian reporting periods.","reference":"Section 2(41)"},{"title":"Obtain Board authority","detail":"Approve the proposed reporting period and reasons. Prepare the certified Board resolution, attendance and voting details, authorisation and details of earlier applications.","reference":"Incorporation Rule 40"},{"title":"Apply to the Regional Director","detail":"Prepare RD-1 and supporting evidence, pay the prescribed fee and respond to any request for correction. Keep the application number and signed approval.","reference":"Section 2(41) · Incorporation Rule 40"},{"title":"Implement the approved period","detail":"File the order in INC-28 within 30 days of receipt of the order. Update the accounting and compliance calendars in line with the precise period authorised.","reference":"Incorporation Rule 40"}],"materials":[{"title":"Overseas consolidation evidence","detail":"Ask the foreign group controller for written confirmation of its year-end and consolidation requirement. Obtain the group chart, financial statements and the certified Board resolution from the local custodian."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find RD-1 and INC-28. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Foreign consolidation requirement evidenced","Board decision, directors present and votes recorded","RD-1 and supporting documents submitted","Approval and INC-28 filing saved","Reporting periods updated"],"variants":[],"also":["annual-filing"]},{"id":"csr","title":"Manage CSR approvals, spend and reporting","category":"Company administration","summary":"The CSR Committee, the policy, the spend, and the yearly reporting.","scope":"Where the statutory financial thresholds apply or the company has continuing obligations for an earlier CSR period.","related":["act-135","act-198","rule-csr-4","rule-csr-5","rule-csr-8"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Determine applicability and budget","detail":"Use the preceding financial year to test section 135 thresholds. Calculate the spend using the relevant average net profits and compare any earlier excess, set-off and unspent sums.","reference":"Sections 135 and 198"},{"title":"Set governance and policy","detail":"Determine whether the Board can discharge the CSR Committee functions under the applicable exception. Prepare the policy, annual action plan, project classification and governance approvals.","reference":"Section 135 · CSR Rules"},{"title":"Screen projects and agencies","detail":"Match projects to Schedule VII. Obtain each implementing agency’s eligibility evidence and CSR registration number where required. CSR-1 is the eligible implementing entity’s registration.","reference":"CSR Rule 4 · Schedule VII"},{"title":"Track expenditure and unspent funds","detail":"Maintain project ledgers and utilisation certification. Separate ongoing projects from other unspent amounts, arrange the required transfers and check impact assessment obligations.","reference":"Section 135(5)–(6) · CSR Rules"},{"title":"Report the year","detail":"Prepare the annual CSR report and Board’s report disclosures, approved website disclosures and applicable CSR-2 reporting with the financial-statements filing. Retain resolutions and bank evidence.","reference":"Section 135 · CSR Rules · Accounts Rule 12"}],"materials":[{"title":"Project and utilisation records","detail":"Request implementing-agency registration and eligibility records, project approvals and utilisation evidence. Ask finance to reconcile project spending to bank statements, budgets and unspent account transfers."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find CSR-2 and any required linked financial filing. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Threshold and spend computation complete","Committee requirement, policy and action plan approved","Implementing agency eligibility and CSR-1 details verified where applicable","Project utilisation, transfers and impact assessment checked","Board’s report, annual CSR report and CSR-2 completed as applicable"],"variants":[],"also":["committees","annual-filing"]},{"id":"secretarial-audit","title":"Arrange secretarial audit and compliance reporting","category":"Company administration","summary":"Appointing the secretarial auditor, the audit report in Form MR-3, and the report for listed companies.","scope":"Companies subject to section 204 or applicable listed-entity and material-subsidiary requirements.","related":["act-134","act-204","rule-managerial-9","lodr-24A"],"templates":["board-notice","resolution-extract"],"steps":[{"title":"Determine audit coverage","detail":"Test company class, financial thresholds and listing category. Identify material Indian unlisted subsidiaries and the reports applicable to the audit period.","reference":"Section 204 · Managerial Personnel Rule 9 · LODR Regulation 24A"},{"title":"Appoint an eligible auditor","detail":"Check the practising company secretary’s eligibility, conflicts and consent. For listed entities address peer review, term limits and required shareholder approval on the Board’s recommendation.","reference":"Section 204 · LODR Regulation 24A"},{"title":"Prepare the records and responses","detail":"Supply the statutory registers, minutes, exchange disclosures, filing receipts and identified exceptions. Obtain a list of queries and retain management’s evidence and responses.","reference":"Section 204"},{"title":"Complete both reporting routes","detail":"Obtain MR-3 where required, annex the report to the Board’s report and address qualifications. Separately obtain and file the applicable annual secretarial compliance report with the exchanges and retain acknowledgement.","reference":"Sections 134 and 204 · LODR Regulation 24A"}],"materials":[{"title":"Audit evidence and consent","detail":"Ask the practising company secretary for eligibility, peer review and engagement documents where applicable. Collate statutory registers, minutes, filing receipts, exchange announcements and management responses."},{"title":"Obtain signed reports","detail":"Request a signed MR-3 from the appointed practising company secretary against the audit engagement. Where LODR applies, separately request the signed annual secretarial compliance report and reconcile it with the exchange filing."}],"checks":["Auditor eligibility, peer-review status and independence checked as applicable","Board and any required shareholder approval retained","Evidence and management replies indexed","Signed MR-3 and Board response received","Exchange compliance report filed where applicable"],"variants":[],"also":["annual-filing","statutory-registers"]},{"id":"statutory-registers","title":"Maintain statutory registers and minute books","category":"Company administration","summary":"Identify the required registers, reconstruct missing entry evidence and arrange lawful custody and inspection.","scope":"Set up or review the books kept by an Indian company. Choose registers according to its securities, transactions and legal class.","related":["act-85","act-88","act-94","act-118","act-128","act-170","act-186","act-189"],"templates":[],"steps":[{"title":"Map required registers","detail":"Identify members and security holders, directors and interests, charges, loans and guarantees, investments, deposits and securities-specific registers that apply. Assign a custodian to each.","reference":"Sections 85, 88, 170, 186–189"},{"title":"Reconcile the underlying records","detail":"Obtain the latest depository or registrar statements, Board approvals, charge certificates and disclosures. Enter each event in its proper register with dates and authorisation.","reference":"Sections 85, 88 and 170"},{"title":"Maintain minutes and accounting books separately","detail":"Keep separate Board, committee and general-meeting records and complete entries and signatures within their prescribed periods. Agree the location and retention of accounting books with finance.","reference":"Sections 118 and 128"},{"title":"Control custody and inspection","detail":"Check the statutory location, resolution and notice required before moving a particular record. For an inspection request verify entitlement, fees, hours and copies, and log the response.","reference":"Sections 94, 119, 128 and 171"}],"materials":[{"title":"Opening positions and past records","detail":"Ask the predecessor custodian, RTA, finance and banks for opening registers and confirmations. Reconstruct missing entries from signed minutes, allotment returns and charge certificates and document the supporting evidence."},{"title":"Obtain filed evidence","detail":"Collect the company’s past accepted filing and acknowledgement from its MCA filing history. Where the company lacks a copy, request public document inspection or a certified copy for the CIN and relevant year."}],"checks":["Registers such as MGT-1, MGT-2, SH-2, SH-3, SH-6, SH-10, CHG-7, MBP-2, MBP-3 and MBP-4","minutes books","books of account","inspection register."],"variants":[],"also":["director-interests","annual-filing"]},{"id":"share-transfer","title":"Process transfer, transmission or replacement of securities","category":"Share capital","summary":"Registering a transfer, a transmission on death, and replacing a lost or damaged certificate.","scope":"Check whether securities are dematerialised or subject to mandatory dematerialisation. Physical transfer procedures apply only where legally available.","related":["act-46","act-56","act-58","act-72","rule-share-capital-6"],"templates":["resolution-extract"],"steps":[{"title":"Classify the request","detail":"Identify sale or gift, transmission by law, a lost certificate or a damaged certificate. Obtain the folio or demat statement, company class, security type and articles.","reference":"Sections 44, 46, 56 and 72"},{"title":"For a transfer","detail":"Where a physical transfer is lawful, verify execution, stamping, certificate and the section 56 delivery period. For dematerialised securities use the depository process through the holder’s participant or RTA.","reference":"Section 56 · Share Capital Rules"},{"title":"For a transmission","detail":"Obtain the death certificate, nomination or evidence of succession, claimant identity and depository or RTA requirements for that holding. Verify title without requiring a transfer deed for a transmission by law.","reference":"Sections 56 and 72"},{"title":"For loss or damage","detail":"Obtain holder particulars, documentary proof and indemnity as required for the case. Follow the company, exchange or depository replacement procedure and document the approval and register entry.","reference":"Section 46 · Share Capital Rule 6"},{"title":"Complete or notify refusal","detail":"Update the register and confirm issue or credit. If refusing registration, apply the company-specific section 58 provisions on reasons, notice and appeal and retain the correspondence.","reference":"Sections 56, 58 and 88"}],"materials":[{"title":"Holder and succession evidence","detail":"Ask the holder’s depository participant or RTA for the holding statement and event-specific requirements. Request the relevant instrument, death certificate, nomination or succession evidence, or loss documentation."},{"title":"Obtain a missing instrument or title record","detail":"Ask the RTA for the checklist for the specific holding and event. Collect original or properly authenticated succession records from the claimant and a fresh depository statement from the authorised participant."}],"checks":["Demat or physical route confirmed","Transfer or succession documents verified","Approved loss or renewal documents retained where applicable","Decision and holder record reconciled","Any refusal and appeal particulars sent within applicable time"],"variants":[],"also":["statutory-registers"]},{"id":"independent-director","title":"Appoint an independent director","category":"Directors","summary":"Eligibility, databank registration, the declarations, the approvals and the filing.","scope":"Distinguish first appointment, reappointment and a casual or interim Board appointment. Apply the relevant LODR conditions for listed entities.","related":["act-149","act-150","act-152","rule-directors-4","rule-directors-6","lodr-25"],"templates":["dir-2","mbp-1"],"steps":[{"title":"Verify independence and capacity","detail":"Collect the candidate’s profile, interests, relationships, prior appointments and declaration against the independence tests. Check databank registration and applicable proficiency-test exemption or result.","reference":"Sections 149–150 · Directors Rules 4–6"},{"title":"Evaluate and recommend","detail":"Obtain the nomination committee assessment when required, ensure the right mix of independence and skills, and record the recommendation and proposed term.","reference":"Sections 149 and 178 · LODR Regulations 17 and 19"},{"title":"Arrange the approvals","detail":"Obtain written consent and disqualification declaration and secure the applicable Board and members’ approvals. Test special resolution requirements for reappointment and the distinct listed-entity appointment provisions and exceptions.","reference":"Sections 149–152 · LODR Regulations 17 and 25"},{"title":"Issue terms and file","detail":"Give the formal appointment letter, attend to inspection and website disclosure of terms and file DIR-12. File MGT-14 for a registrable resolution and make the applicable exchange disclosure.","reference":"Schedule IV · Sections 117 and 170 · LODR Regulation 30"},{"title":"Maintain independence evidence","detail":"Calendar the annual declaration, changes in circumstances, separate meeting of independent directors, familiarisation and evaluation. Track the end of the appointment term.","reference":"Section 149(7) · Schedule IV · LODR Regulation 25"}],"materials":[{"title":"Independence and databank checks","detail":"Ask the candidate for the signed declarations, directorship history, related-party relationships and databank status. Have the NRC record its due diligence and evaluation against the actual role."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find DIR-12 and, for a registrable resolution, MGT-14. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Consent, independence and disqualification declarations on file","Databank and proficiency conditions checked","NRC, Board and member approvals obtained as applicable","Appointment terms and changes circulated","Returns and exchange reporting reconciled"],"variants":[],"also":["appoint-director","committees"]},{"id":"dormant-company","title":"Obtain or end dormant status","category":"Company status","summary":"Applying to be treated as a dormant company, filing the yearly return, and returning to active status.","scope":"For a future project, asset-holding company or qualifying inactive company, subject to statutory eligibility and the exclusions in the rules.","related":["act-455","rule-the-companies-miscellaneous-rules-2014-3","rule-the-companies-miscellaneous-rules-2014-7"],"templates":["resolution-extract"],"steps":[{"title":"Test eligibility and exclusions","detail":"Check activity, significant accounting transactions, securities, taxes, deposits, borrowings and pending proceedings. Obtain any required lender concurrence and reconcile assets and liabilities.","reference":"Section 455 · Miscellaneous Rule 3"},{"title":"Obtain approval and apply","detail":"Pass a special resolution or give notice to all shareholders and obtain the statutory three-fourths-in-value consent. File MSC-1 with supporting records and retain the Registrar’s certificate in MSC-2.","reference":"Section 455 · Miscellaneous Rules 3–4"},{"title":"Meet continuing duties","detail":"Maintain the minimum directors, accounts and registers. File the dormant-company return MSC-3 with the prescribed audited financial position, and assess other applicable event and annual filings.","reference":"Section 455 · Miscellaneous Rules 6–7"},{"title":"Reactivate when needed","detail":"Assess the effective event or voluntary decision, file MSC-4 with the necessary return and obtain the active-status certificate. Respond separately to any Registrar notice on inactivity or prolonged dormant status.","reference":"Section 455 · Miscellaneous Rules"}],"materials":[{"title":"Eligibility and shareholder authority","detail":"Obtain an accountant-prepared statement of affairs, loan and dues confirmations and any lender consent. Reconcile the member consent calculation with the register measured by value."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find MSC-1, MSC-3 or MSC-4. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Dormant-status eligibility documented","Special resolution or prescribed notice and consent retained","Statement of affairs and applicable lender consent obtained","MSC-1 and certificate saved","Dormant return or reactivation dates recorded"],"variants":[],"also":["strike-off","annual-filing"]},{"id":"beneficial-owners","title":"Identify and report beneficial ownership","category":"Company administration","summary":"Finding who owns or controls the company, the declarations, the return to the Registrar and the register.","scope":"Distinguish section 89 declarations of beneficial interest from the separate significant beneficial owner tests under section 90.","related":["act-89","act-90","rule-sbo-3","rule-sbo-5"],"templates":[],"steps":[{"title":"Map the chain of ownership","detail":"Start from registered members and trace intermediate entities to individuals. Test indirect holdings and rights, influence or control, relevant aggregation and exemptions. Keep beneficial-interest and SBO findings separate.","reference":"Sections 89–90 · SBO Rules"},{"title":"Record general declarations","detail":"Obtain MGT-4 and MGT-5 where section 89 applies. Record receipt, update the register and file the applicable MGT-6 return within the prescribed period.","reference":"Section 89 · Management and Administration Rule 9"},{"title":"Record significant beneficial owners","detail":"Obtain BEN-1 where required, date-stamp the declaration or change and maintain BEN-3. File BEN-2 within 30 days of receipt of the declaration.","reference":"Section 90 · SBO Rules 3–5"},{"title":"Investigate missing information","detail":"Send BEN-4 when a statutory enquiry is triggered, set the response deadline and examine the evidence. For non-response or unsatisfactory particulars, apply to the Tribunal within 15 days after the notice period expires as section 90(7) requires.","reference":"Section 90(5)–(7) · SBO Rules 6–7"}],"materials":[{"title":"Beneficial ownership chain","detail":"Request ownership and control information from each registered corporate member, including intermediate holding entities and significant interests. Ask the relevant individuals for dated declarations and evidence of changes."},{"title":"Obtain the filing form","detail":"In the authorised MCA account, open Company e-Filing and find BEN-2 for the SBO return, or MGT-6 for section 89 beneficial-interest declarations. Select the relevant event and company, obtain the current attachment list, and reconcile names and dates to the signed records. After submission, save the SRN, receipt and final status in the matter file."}],"checks":["Holding chain and exemptions documented","MGT-4, MGT-5 and MGT-6 considered separately","BEN-1 received and BEN-3 updated where applicable","BEN-2 acknowledged","Any BEN-4 notice and Tribunal application tracked"],"variants":[],"also":["statutory-registers"]},{"id":"book-closure","title":"Fix a record date or close the register","category":"Shareholders","summary":"Deciding who is entitled to a dividend or to attend a meeting, and the notices to give.","scope":"For a dividend, corporate action or other event. Record dates, book closures and voting cut-off dates serve different purposes.","related":["act-91","act-127","rule-management-10","lodr-42"],"templates":["resolution-extract"],"steps":[{"title":"Confirm the event and dates","detail":"Agree the entitlement with finance and the RTA, apply the relevant approval and timing rules and document whether the register will close or remain open on a record date.","reference":"Section 91 · LODR Regulation 42"},{"title":"Give the required notice","detail":"For a register closure, calculate the statutory prior notice and maximum closure periods. Check newspaper, website and company-class requirements and retain the announcement or delivery proof.","reference":"Section 91 · Management and Administration Rule 10"},{"title":"For listed securities notify the exchanges","detail":"Check the type of corporate action. The usual Regulation 42 record-date notice is at least three working days, excluding intimation and record dates. The specified scheme route under Regulation 37 requires seven working days. Check other applicable gaps and exchange conditions.","reference":"LODR Regulations 37 and 42"},{"title":"Reconcile the entitlement list","detail":"Confirm the holder list at the relevant cut-off with the RTA or depository. Execute the dividend or allotment, reopen the register if closed and retain the Board record and reconciled list.","reference":"Sections 88, 91 and 127"}],"materials":[{"title":"Register dates and exchange evidence","detail":"Ask the RTA or depository to confirm corporate-action dates and entitlement cut-off. Obtain the Board decision, copies of statutory notices and any exchange acknowledgement before finalising the list."},{"title":"Obtain the entitlement file","detail":"Request a dated beneficiary position or member list through the RTA or depository using the ISIN and effective record date. Check its total against issued capital and retain the final reconciled file."}],"checks":["Purpose and holder cut-off approved","Publication or exchange timings checked","Delivery or exchange evidence retained","Final holder list reconciled to the register"],"variants":[],"also":["dividend","allotment"]}],"guides":[]});
